const body = $json.body ?? $json;
const rawAds = Array.isArray(body.ads) ? body.ads : [];

if (!rawAds.length) {
  throw new Error('MR05 wymaga body.ads[].');
}
if (rawAds.length > 200) {
  throw new Error(`MR05 przyjmuje maksymalnie 200 reklam na wywołanie; otrzymano ${rawAds.length}.`);
}

function clean(value, max = 1400) {
  return String(value ?? '')
    .replace(/<[^>]*>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, max);
}

const ads = rawAds.map(ad => ({
  adArchiveId: clean(ad.adArchiveId ?? ad.ad_archive_id ?? ad.metaAdId ?? ad.id, 120),
  pageName: clean(ad.pageName ?? ad.page_name, 250),
  title: clean(ad.title ?? ad.headline, 350),
  body: clean(ad.bodyText ?? ad.body_text ?? ad.body ?? ad.adText, 1400),
  description: clean(ad.description ?? ad.adLinkDescription, 350),
  linkUrl: clean(ad.destinationUrl ?? ad.destination_url ?? ad.adLibraryUrl ?? ad.ad_library_url, 500),
  startDate: ad.startDate ?? ad.start_date ?? null,
  endDate: ad.endDate ?? ad.end_date ?? null,
  isActive: ad.isActive ?? ad.is_active ?? null,
  longevityCategory: ad.longevityCategory ?? ad.longevity_category ?? null,
  runtimeDays: ad.runtimeDays ?? ad.runtime_days ?? null,
  mr04Decision: ad.mr04Decision ?? null,
  mr04Confidence: ad.mr04Confidence ?? null,
  mr04ReasonCode: clean(ad.mr04ReasonCode, 100),
  mr04Reason: clean(ad.mr04Reason, 500),
  matchedQueries: Array.isArray(ad.matchedQueries) ? ad.matchedQueries.slice(0, 12) : [],
  matchedSeeds: Array.isArray(ad.matchedSeeds) ? ad.matchedSeeds.slice(0, 12) : [],
})).filter(ad => ad.adArchiveId);

if (!ads.length) {
  throw new Error('MR05 nie znalazł żadnego poprawnego identyfikatora reklamy.');
}

return [{
  json: {
    projectId: String(body.projectId ?? body.project_id ?? 'default'),
    filterVersion: 'mr05-second-pass-v2',
    batch: {
      index: Number(body.batch?.index ?? 1),
      total: Number(body.batch?.total ?? 1),
      size: ads.length,
    },
    projectContext: {
      projectName: body.projectName ?? null,
      projectBrief: body.projectBrief ?? body.brief ?? null,
      queryPlan: body.queryPlan ?? null,
    },
    ads,
  },
}];

const source = $('Normalize Input').first().json;
const output = $json.output ?? $json;
let parsed = output;

if (typeof parsed === 'string') {
  const cleaned = parsed.trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');
  try {
    parsed = JSON.parse(cleaned);
  } catch {
    parsed = {};
  }
}

const expectedIds = source.ads.map(ad => String(ad.adArchiveId));
const expected = new Set(expectedIds);
const allowedDecision = new Set(['KEEP', 'REJECT', 'REVIEW']);
const reasonByDecision = {
  KEEP: new Set(['IN_SCOPE', 'ADJACENT_IN_SCOPE']),
  REJECT: new Set(['OUT_OF_SCOPE_TOPIC', 'ACCIDENTAL_KEYWORD_MATCH', 'NON_MARKET_NOISE']),
  REVIEW: new Set(['INSUFFICIENT_DATA', 'AMBIGUOUS']),
};
const byId = new Map();

for (const item of Array.isArray(parsed?.decisions) ? parsed.decisions : []) {
  const id = String(item?.adArchiveId ?? '').trim();
  if (!expected.has(id) || byId.has(id)) continue;

  let decision = String(item?.decision ?? 'REVIEW').toUpperCase();
  if (!allowedDecision.has(decision)) decision = 'REVIEW';

  let reasonCode = String(item?.reasonCode ?? 'AMBIGUOUS').toUpperCase();
  if (!reasonByDecision[decision].has(reasonCode)) {
    decision = 'REVIEW';
    reasonCode = 'AMBIGUOUS';
  }

  let confidence = Number(item?.confidence);
  if (!Number.isFinite(confidence)) confidence = 0;
  confidence = Math.max(0, Math.min(100, Math.round(confidence)));

  byId.set(id, {
    adArchiveId: id,
    decision,
    confidence,
    reasonCode,
    reason: cleanReason(item?.reason),
  });
}

function cleanReason(value) {
  return String(value ?? '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 400) || 'Brak kompletnej decyzji modelu; wymagana weryfikacja.';
}

const missingIds = [];
for (const id of expectedIds) {
  if (!byId.has(id)) {
    missingIds.push(id);
    byId.set(id, {
      adArchiveId: id,
      decision: 'REVIEW',
      confidence: 0,
      reasonCode: 'INSUFFICIENT_DATA',
      reason: 'Brak kompletnej decyzji modelu; wymagana weryfikacja.',
    });
  }
}

const decisions = expectedIds.map(id => byId.get(id));

return [{
  json: {
    ok: true,
    degraded: missingIds.length > 0,
    projectId: source.projectId,
    filterVersion: source.filterVersion,
    processedAt: new Date().toISOString(),
    batch: source.batch,
    missingIds,
    summary: {
      total: decisions.length,
      keep: decisions.filter(item => item.decision === 'KEEP').length,
      reject: decisions.filter(item => item.decision === 'REJECT').length,
      review: decisions.filter(item => item.decision === 'REVIEW').length,
    },
    decisions,
  },
}];
